WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_judgement_definition_multi_matching'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '匹配类定义', 'kp-xingce-judgement-definition-multi-matching', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多定义：匹配类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "各找各妈。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、解题步骤"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干给出 3 个定义。选项列出 4 个例子。分别判断每个例子属于哪个定义。这种题不需要深刻理解定义，只抓核心特征词进行对号入座。"}]}]}$$ AS jsonb), NULL, '匹配类定义的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "匹配类定义"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_definition_multi_matching", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
